package com.gamehub.application.controller; import com.gamehub.application.service.MatchService; import java.time.Instant; import java.util.List; public final class MatchController {private final MatchService service;public MatchController(MatchService s){service=s;}public List<String> matches(long t)throws Exception{return service.matches(t);}public List<String> participants(long m)throws Exception{return service.participants(m);}public List<Long> generate(long a,long t)throws Exception{return service.generate(a,t);}public void schedule(long a,long m,long st,Instant when)throws Exception{service.schedule(a,m,st,when);}public void start(long a,long m)throws Exception{service.start(a,m);}public void result(long a,long m,int x,int y,long w)throws Exception{service.result(a,m,x,y,w);}public void correct(long a,long m,int x,int y,long w,String r)throws Exception{service.correct(a,m,x,y,w,r);}}